        &lt;span class=&quot;stat-sub&quot;&gt;Batas waktu sebelum pesanan kedaluwarsa&lt;/span&gt;
    &lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;form-grid&quot;&gt;
    &lt;div&gt;
        &lt;section class=&quot;panel panel-accent&quot;&gt;
            &lt;div class=&quot;panel-head&quot;&gt;
                &lt;div&gt;
                    &lt;h2&gt;Webhook pembayaran&lt;/h2&gt;
                    &lt;p&gt;Alamat yang didaftarkan di dashboard Midtrans.&lt;/p&gt;
                &lt;/div&gt;
            &lt;/div&gt;
            &lt;div class=&quot;panel-body&quot;&gt;
                &lt;p class=&quot;form-hint&quot;&gt;Buka Midtrans, masuk ke Settings, lalu isi Payment Notification URL dengan alamat berikut. Jangan menambahkan garis miring di akhir.&lt;/p&gt;
                &lt;div class=&quot;code-line&quot;&gt;
                    &lt;code&gt;http://localhost:8080/webhook/midtrans&lt;/code&gt;
                    &lt;button class=&quot;btn btn-ghost btn-small&quot; type=&quot;button&quot; data-copy=&quot;http://localhost:8080/webhook/midtrans&quot;&gt;Salin&lt;/button&gt;
                &lt;/div&gt;

                &lt;dl class=&quot;kv&quot; style=&quot;margin-top: 20px;&quot;&gt;
                    &lt;dt&gt;Driver aktif&lt;/dt&gt;
                    &lt;dd&gt;&lt;span class=&quot;chip chip-warn&quot;&gt;Sandbox&lt;/span&gt;&lt;/dd&gt;

                    &lt;dt&gt;Server key&lt;/dt&gt;
                    &lt;dd&gt;&lt;span class=&quot;chip chip-danger&quot;&gt;Kosong&lt;/span&gt;&lt;/dd&gt;

                    &lt;dt&gt;Mode Midtrans&lt;/dt&gt;
                    &lt;dd&gt;Sandbox&lt;/dd&gt;

                    &lt;dt&gt;Alamat Snap&lt;/dt&gt;
                    &lt;dd style=&quot;font-size: 11.5px;&quot;&gt;https://app.sandbox.midtrans.com/snap/v1/transactions&lt;/dd&gt;
                &lt;/dl&gt;

                                    &lt;div class=&quot;alert-box&quot; style=&quot;margin-top: 18px; margin-bottom: 0;&quot;&gt;
                        &lt;div&gt;
                            &lt;strong&gt;Pembayaran masih memakai simulator.&lt;/strong&gt;
                            Jangan gunakan mode ini untuk menerima uang sungguhan. Isi MIDTRANS_SERVER_KEY dan MIDTRANS_CLIENT_KEY, lalu set PAYMENT_DRIVER = midtrans untuk beralih.
                        &lt;/div&gt;
                    &lt;/div&gt;
                            &lt;/div&gt;
        &lt;/section&gt;

        &lt;section class=&quot;panel&quot; style=&quot;margin-top: 22px;&quot;&gt;
            &lt;div class=&quot;panel-head&quot;&gt;
                &lt;div&gt;
                    &lt;h2&gt;Pengiriman email&lt;/h2&gt;
                    &lt;p&gt;Email invoice dan akses dikirim setelah pembayaran terverifikasi.&lt;/p&gt;
                &lt;/div&gt;
            &lt;/div&gt;
            &lt;div class=&quot;panel-body&quot;&gt;
                &lt;dl class=&quot;kv&quot;&gt;
                    &lt;dt&gt;Driver aktif&lt;/dt&gt;
                    &lt;dd&gt;&lt;span class=&quot;chip chip-warn&quot;&gt;File lokal&lt;/span&gt;&lt;/dd&gt;

                    &lt;dt&gt;Alamat pengirim&lt;/dt&gt;
                    &lt;dd&gt;halo@namausaha.test&lt;/dd&gt;

                    &lt;dt&gt;Nama pengirim&lt;/dt&gt;
                    &lt;dd&gt;Nama Usaha&lt;/dd&gt;

                    &lt;dt&gt;Host SMTP&lt;/dt&gt;
                    &lt;dd&gt;smtp.gmail.com:587&lt;/dd&gt;

                    &lt;dt&gt;Enkripsi&lt;/dt&gt;
                    &lt;dd&gt;TLS&lt;/dd&gt;

                    &lt;dt&gt;Pengguna SMTP&lt;/dt&gt;
                    &lt;dd&gt;-&lt;/dd&gt;
                &lt;/dl&gt;

                                    &lt;p class=&quot;form-hint&quot;&gt;Mode file menulis email ke folder &lt;code&gt;writable/emails&lt;/code&gt;. Email tidak benar-benar terkirim. Isi MAIL_SMTP_USER dan MAIL_SMTP_PASS dengan akun Gmail dan App Password, lalu set MAIL_DRIVER = smtp.&lt;/p&gt;

                &lt;form action=&quot;http://localhost:8080/admin/pengaturan/uji-email&quot; method=&quot;post&quot; style=&quot;margin-top: 18px;&quot; data-confirm=&quot;Kirim email uji ke admin@nexusdiji.test?&quot;&gt;
                    &lt;input type=&quot;hidden&quot; name=&quot;csrf_test_name&quot; value=&quot;e6011ec19e656dfa448252e6f022b3c3&quot;&gt;                    &lt;button class=&quot;btn btn-primary btn-small&quot; type=&quot;submit&quot;&gt;Kirim email uji&lt;/button&gt;
                &lt;/form&gt;
                &lt;p class=&quot;form-hint&quot;&gt;Email uji dikirim ke admin@nexusdiji.test. Pada mode file, hasilnya muncul di daftar bawah.&lt;/p&gt;
            &lt;/div&gt;
        &lt;/section&gt;

        &lt;section class=&quot;panel&quot; style=&quot;margin-top: 22px;&quot;&gt;
            &lt;div class=&quot;panel-head&quot;&gt;
                &lt;div&gt;
                    &lt;h2&gt;Email terakhir di folder lokal&lt;/h2&gt;
                    &lt;p&gt;Hanya terisi saat driver email memakai mode file.&lt;/p&gt;
                &lt;/div&gt;
            &lt;/div&gt;
            &lt;div class=&quot;panel-body&quot;&gt;
